    "Soldier/Marine 士兵、海军陆战队士兵",
    "Spy 间谍",
    "Street Punk 混混：参考罪犯",
    "Student/Intern 学生、实习生",
    "Stuntman 替身演员",
    "Taxi Driver 出租车司机：参考司机",
    "Thug 暴徒：参考罪犯",
