# mbti列表
mbti_list = ["INFP：调停者（Mediator）“凡是金子未必都发光，流浪的人未必都迷茫，老而弥坚者不会凋零，深根不会被寒霜触及。（托尔金）”",
             "INTP：逻辑学家（Logician）“借鉴昨天，活在今天，憧憬明天。 重要的是绝不停止质疑。（爱因斯坦）”",
             "INTJ：建筑师（Architect）“你并非有权力发表看法。你的权利是发表有根据的看法。没人有无知的权利。（哈伦·埃利森）”",
             "INFJ：提倡者/倡导者（Advocate）“每个人都需要做出选择，是走在富有创造力的利他主义之光中，还是具有破坏性的自私自利的黑暗中。（马丁·路德·金）”",
             "ENFP：竞选者（Campaigner）“你用什么谋生方式，我不关心；我想知道，你的追求，你是否敢于梦想去触碰你内心的渴望。你的年龄多大，我不关心；我想知道，你是否愿意像傻瓜一样不顾风险，为了爱，梦想，还有活着就该有的冒险。（山居梦客(Oriah Mountain Dreamer)）”",
             "ENTP：辩论家（Debater）“追寻危险而独立的思想者的脚步。不畏争议表达观点。说出你的想法，宁愿被当作精神病也不受盲从的耻辱。对于你认为重要的问题，无论如何也要表达立场且坚决拥护。（托马斯·约翰·沃森）”",
             "ENTJ：指挥官（Commander）“你的时间是有限的，所以不要浪费它为别人而活。不要陷入教条 — 活在其他人的思想成果之中。不要让他人意见产生的噪音淹没你自己的心声。最重要的是，要拥有追随你的内心和直觉的勇气。他们已经知道你真正想成为什么。其他所有都是次要的。（史蒂夫·乔布斯）”",
             "ENFJ：主人公（Protagonist）“你此时此刻做的任何事都会激起涟漪影响他人。你的姿态可以照亮心扉也可以传播焦虑。你的气息可以将爱散发也可以使愁云笼罩。你的一瞥可以唤起欢乐。你的言语可以启发自由。你的每个动作都可能打开一扇心灵之窗。（大卫·戴达）”",
             "ISFP：探险家（Adventurer）“在一天中我会变化。醒来时是一个人，睡觉时却明明是另一个人。（鲍勃·迪伦）”",
             "ISTP：鉴赏家/艺术能手（Virtuoso）“我想要享受人生，一个不同的人生。我不想每天去去到同一个地方，遇见同样的人，做一样的工作。我期待有趣的挑战。（哈里森·福特）”",
             "ISTJ：物流师/军需官（Logistician）“我的观察是每当某个任务一个人就可以完成… 两个人就会做得更差，三个或更多人时则几乎没什么行动。（华盛顿）”",
             "ISFJ：守卫者（Defender）“只有分享才能把爱增加。只用奉献更多才能得到更多。（博恩·崔西）”",
             "ESFP：表演者（Entertainer）“我自私，没耐心，还有点缺少安全感。我会犯错，会失控，而且有时让人难以应付。但如果你接受不了我最坏的一面，你就不配拥有我最好的一面。（玛丽莲·梦露）”",
             "ESTP：企业家（Entrepreneur）“生活，要么是场大胆的冒险，要么什么都不是。（海伦·凯勒）”", "ESTJ:总经理/执行官（Executive）“良好的秩序是一切的基础。（埃德蒙·伯克）”",
             "ESFJ：执政官（Consul）“让我们互相支持，鼓舞，赋予力量。 让每个人的正能量都被所有人感受到。（黛博拉·戴）”"]
