    def random_entry_for_new_roles_NPC_by_mock(self, event):
        if self.description_text.get("1.0", tk.END) == "" or self.description_text.get("1.0",
                                                                                       tk.END) == "未查找到此条目！" or self.description_text.get(
            "1.0", tk.END) == "技能一10 技能二30 技能三70":
            self.description_text.delete("1.0", tk.END)
            self.description_text.insert(tk.END, f"信用{random.randint(1, 100)}")
        elif "信用" in self.description_text.get("1.0", tk.END):
            credit = self.description_text.get("1.0", tk.END).split("信用")[1].split(" ")[0]
            self.description_text.delete("1.0", tk.END)
            self.description_text.insert(tk.END, self.description_text.get("1.0", tk.END).replace(credit,
                                                                                                  f"信用{random.randint(1, 100)}"))
        replacemant = self.name_entry.get().split("=")[0] + "=" + random.choice(career_list)
        self.name_entry.delete(0, tk.END)
        self.name_entry.insert(tk.END, replacemant)
        type_mock = self.type_var.get()
        if type_mock == "无预设" or type_mock == "请选择预设":
            self.EDU_text.delete(0, tk.END)
            self.APP_text.delete(0, tk.END)
            self.DEX_text.delete(0, tk.END)
            self.STR_text.delete(0, tk.END)
            self.INT_text.delete(0, tk.END)
            self.CON_text.delete(0, tk.END)
            self.POW_text.delete(0, tk.END)
            self.SIZ_text.delete(0, tk.END)
            self.LUCK_text.delete(0, tk.END)
