            self.APP_text.insert(tk.END, mock_dic.get("外貌"))
            self.DEX_text.insert(tk.END, mock_dic.get("敏捷"))
            self.STR_text.insert(tk.END, mock_dic.get("力量"))
            self.INT_text.insert(tk.END, mock_dic.get("智力"))
            self.CON_text.insert(tk.END, mock_dic.get("体质"))
            self.POW_text.insert(tk.END, mock_dic.get("意志"))
