                            entry2 = tk.Text(frame, wrap=tk.WORD, width=10, height=6, undo=True)
                            entry2.grid(row=1, column=2, padx=5, pady=5, sticky="nsew")
                            value_tag = f"{NPC_name}_values_tag"
