                sorted_ids = sorted(self.tree2_list[role].get_children(),
                                    key=lambda x: self.tree2_list[role].set(x, "记忆指数"),
                                    reverse=True)
                # 遍历排序后的条目ID，将它们插入到新的 Treeview 中
